const done = new Set($('Read CRM (comments)').all().map(r => String(r.json['IG user id'] || '')).filter(Boolean));
const seen = new Set();
return $('Classify').all().filter(i => i.json.action === 'keyword_comment').filter(i => {
  const id = String(i.json.senderId);
  if (done.has(id) || seen.has(id)) return false;
  seen.add(id); return true;
}).map(i => ({ json: i.json }));

const rows = $('Read CRM (comments)').all().map(r => r.json).filter(r => r['IG user id']);
